// Phase 4 / Module 16: Database Programming.
// SQLite examples use only the standard library. The SQLAlchemy example needs `pip install "sqlalchemy>=2.0,<2.1"`.
// The MySQL lesson shows code that needs a running MySQL server, so its connection code is illustrated, not executed.
"use strict";
const { chain, graph, table, terminal, svgWrap, esc } = require("./render");
const { mcq, task } = require("./lib");

const lessons = [];
const tx = (x, y, s, size = 13, anchor = "middle") => `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" fill="currentColor" font-family="system-ui,sans-serif">${esc(s)}</text>`;
const entity = (x, y, w, title, fields) => `<rect x="${x}" y="${y}" width="${w}" height="${26 + fields.length * 20}" rx="5" fill="rgba(127,127,127,.10)" stroke="currentColor" stroke-width="1.6"/><line x1="${x}" y1="${y + 26}" x2="${x + w}" y2="${y + 26}" stroke="currentColor" stroke-width="1.2"/>` + tx(x + w / 2, y + 18, title, 14) + fields.map((f, i) => tx(x + 10, y + 44 + i * 20, f, 12, "start")).join("");

// ---------------------------------------------------------------- 1
lessons.push({
  title: "Database Fundamentals: Tables, Keys and the Relational Model",
  minutes: 45,
  learn: ["Explain what a database and a DBMS are", "Describe tables, rows, columns, primary keys and foreign keys", "Compare relational (SQL) and non-relational databases", "State what ACID means"],
  why: "Almost every real application stores its data in a database. Understanding the relational model first makes SQL, Python database code and ORMs much easier.",
  realWorld: "A college system keeps Students, Courses and Enrolments; an online shop keeps Customers, Products, Orders and Payments, all linked by keys.",
  simple: "A <strong>database</strong> is an organised collection of data managed by a <strong>DBMS</strong> (database management system). In a relational database the data lives in <strong>tables</strong> (rows and columns) that are linked by <strong>keys</strong>.",
  detail: `${table(["Term", "Meaning", "Example"], [["table (relation)", "a set of rows with the same columns", "<code>students</code>"], ["row (record, tuple)", "one item", "(1, 'Asha', 'CSE')"], ["column (field, attribute)", "one property, with a type", "<code>name TEXT</code>"], ["primary key", "uniquely identifies a row; never NULL", "<code>id</code>"], ["foreign key", "a column that refers to another table's primary key", "<code>enrolments.student_id</code>"], ["NULL", "unknown or missing value (not zero, not an empty string)", ""], ["constraint", "a rule the database enforces", "NOT NULL, UNIQUE, CHECK, FOREIGN KEY"]])}
<h3>Relational versus other models</h3>
${table(["Kind", "Examples", "Good for"], [["relational (SQL)", "SQLite, MySQL, PostgreSQL, SQL Server, Oracle", "structured data with relationships and transactions"], ["document", "MongoDB", "flexible JSON-like records"], ["key-value", "Redis", "caching, sessions, very fast lookups"], ["wide-column / graph / time-series", "Cassandra, Neo4j, InfluxDB", "specialised workloads"]])}
<h3>ACID transactions</h3>
<ul><li><strong>Atomicity</strong>: all steps of a transaction happen or none do.</li><li><strong>Consistency</strong>: a transaction moves the database from one valid state to another (constraints hold).</li><li><strong>Isolation</strong>: concurrent transactions do not see each other's half-finished work.</li><li><strong>Durability</strong>: once committed, data survives a crash.</li></ul>
<h3>SQLite in this course</h3>
<p>SQLite is a complete SQL database stored in one file (or in memory with <code>":memory:"</code>) and ships inside Python (<code>import sqlite3</code>). It is ideal for learning, small applications, mobile apps and tests. Server databases (MySQL, PostgreSQL) add many users, network access and tuning, but the SQL and the Python code are very similar.</p>`,
  syntax: { code: `CREATE TABLE students (\n    id INTEGER PRIMARY KEY,\n    name TEXT NOT NULL,\n    dept TEXT\n);`, lang: "sql", note: "SQL is declarative: you say what you want, not how to get it." },
  diagram: ((() => { const inner = entity(30, 30, 190, "students", ["id  (PK)", "name", "dept"]) + entity(300, 30, 220, "enrolments", ["id  (PK)", "student_id  (FK)", "course_id  (FK)"]) + entity(590, 30, 190, "courses", ["id  (PK)", "title", "credits"]) + `<line x1="220" y1="80" x2="300" y2="80" stroke="currentColor" stroke-width="1.6" marker-end="url(#ah)"/><line x1="590" y1="80" x2="520" y2="80" stroke="currentColor" stroke-width="1.6" marker-end="url(#ah)"/>` + tx(400, 170, "foreign keys link the tables: one student, many enrolments", 12); return svgWrap(810, 190, "Three related tables", "Tables students, enrolments and courses; enrolments holds foreign keys student_id and course_id pointing to the other two tables.", inner); })()),
  example: { code: `import sqlite3\n\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT NOT NULL, dept TEXT)")\ndb.execute("INSERT INTO students (name, dept) VALUES ('Asha', 'CSE')")\ndb.execute("INSERT INTO students (name, dept) VALUES ('Ravi', NULL)")\nfor row in db.execute("SELECT id, name, dept FROM students ORDER BY id"):\n    print(row)\nprint(db.execute("SELECT COUNT(*), COUNT(dept) FROM students").fetchone())\ntry:\n    db.execute("INSERT INTO students (name) VALUES (NULL)")\nexcept sqlite3.IntegrityError as error:\n    print("rejected:", error)\nprint(sqlite3.sqlite_version_info >= (3, 8))`, out: `(1, 'Asha', 'CSE')\n(2, 'Ravi', None)\n(2, 1)\nrejected: NOT NULL constraint failed: students.name\nTrue` },
  lineByLine: [["sqlite3.connect(\":memory:\")", "A temporary database that lives only in memory."], ["INTEGER PRIMARY KEY", "SQLite numbers the rows automatically."], ["NULL in a Python row", "Becomes <code>None</code>."], ["COUNT(*), COUNT(dept)", "COUNT(*) counts rows; COUNT(column) skips NULLs: 2 and 1."], ["IntegrityError", "The NOT NULL constraint stopped the invalid row."]],
  dryRun: { intro: "What the database holds after the two inserts:", headers: ["id", "name", "dept"], rows: [["1", "Asha", "CSE"], ["2", "Ravi", "NULL"]] },
  realExample: { intro: "Primary key uniqueness is enforced for you.", code: `import sqlite3\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE users (email TEXT PRIMARY KEY, name TEXT)")\ndb.execute("INSERT INTO users VALUES ('a@x.in', 'Asha')")\ntry:\n    db.execute("INSERT INTO users VALUES ('a@x.in', 'Another')")\nexcept sqlite3.IntegrityError:\n    print("duplicate key refused")\nprint(db.execute("SELECT COUNT(*) FROM users").fetchone()[0])`, out: `duplicate key refused\n1` },
  mistakes: ["Using a name or phone number as the primary key when it can change or repeat.", "Treating NULL as 0 or as an empty string.", "Keeping everything in one giant table.", "Skipping constraints and checking in Python only.", "Thinking SQLite is only a toy: it is excellent for many uses."],
  practices: ["Give every table a primary key.", "Put rules in the database as constraints.", "Choose clear, singular or plural names consistently."],
  interview: ["What is the difference between a primary key and a foreign key?", "What does ACID stand for?", "What is NULL?", "SQL versus NoSQL: when would you choose each?"],
  practiceQs: ["Which column would you choose as the key for an Orders table?", "What is the difference between COUNT(*) and COUNT(col)?", "Why is a database better than a CSV file for an application?", "What does durability mean?"],
  revision: ["Tables, rows, columns; PK and FK.", "NULL means unknown.", "ACID: atomicity, consistency, isolation, durability.", "SQLite is a full SQL database inside Python."],
  hinglish: "Relational database mein data tables mein hota hai aur primary key har row ko alag pehchaan deti hai. Foreign key doosre table ki primary key ko jodti hai. NULL ka matlab 'pata nahi', zero ya khali string nahi. Transaction mein ya to saare kaam hote hain ya koi nahi (atomicity).",
  quiz: [
    mcq("What uniquely identifies a row?", ["Foreign key", "Primary key", "Index", "Constraint only"], 1, "The primary key."),
    mcq("What does COUNT(col) skip?", ["Zeros", "NULL values", "Duplicates", "Strings"], 1, "NULLs are ignored by COUNT(column).", "OUTPUT_PREDICTION"),
    mcq("What does the A in ACID mean?", ["Availability", "Atomicity", "Accuracy", "Automation"], 1, "All or nothing."),
    mcq("A foreign key refers to:", ["A primary key of another (or the same) table", "Any column", "A Python variable", "A file"], 0, "It links related rows."),
    mcq("Which database ships inside Python?", ["MySQL", "SQLite", "PostgreSQL", "Oracle"], 1, "import sqlite3.")
  ],
  tasks: [task("Rows and NULLs", "Read n, then n lines each holding a name and a department (or the word NULL for no department). Store them in an SQLite in-memory table and print two numbers: the number of rows and the number of rows that have a department, separated by a space.", "import sqlite3\nn = int(input())\n# create the table, insert the rows (NULL becomes None), count\n", `import sqlite3\nn = int(input())\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE people (name TEXT, dept TEXT)")\nfor _ in range(n):\n    name, dept = input().split()\n    db.execute("INSERT INTO people VALUES (?, ?)", (name, None if dept == "NULL" else dept))\ntotal, with_dept = db.execute("SELECT COUNT(*), COUNT(dept) FROM people").fetchone()\nprint(total, with_dept)`, [["3\nAsha CSE\nRavi NULL\nZoya ECE", "3 2"], ["1\nKiran NULL", "1 0"]], [["3\nAsha CSE\nRavi NULL\nZoya ECE", "3 2"], ["1\nKiran NULL", "1 0"], ["2\nA X\nB X", "2 2"], ["4\na NULL\nb NULL\nc NULL\nd Y", "4 1"]])],
});

// ---------------------------------------------------------------- 2
lessons.push({
  title: "SQL Revision: SELECT, Filtering, Aggregation and JOINs",
  minutes: 60,
  learn: ["Query data with SELECT, WHERE, ORDER BY and LIMIT", "Summarise with COUNT, SUM, AVG, GROUP BY and HAVING", "Combine tables with INNER, LEFT JOINs and subqueries", "Read the logical order in which SQL is evaluated"],
  why: "SQL is the language of data. A few dozen patterns cover most reports, and the same queries work from Python on SQLite, MySQL and PostgreSQL.",
  realWorld: "Top 3 students per department, total sales per month, customers who never ordered.",
  simple: "<code>SELECT</code> columns <code>FROM</code> a table, keep rows that match <code>WHERE</code>, group them with <code>GROUP BY</code>, filter groups with <code>HAVING</code>, sort with <code>ORDER BY</code>, cut with <code>LIMIT</code>.",
  detail: `<h3>Statement parts</h3>
${table(["Clause", "Role"], [["<code>SELECT</code>", "which columns or expressions"], ["<code>FROM</code> / <code>JOIN</code>", "which tables and how they connect"], ["<code>WHERE</code>", "filter rows before grouping"], ["<code>GROUP BY</code>", "make one row per group"], ["<code>HAVING</code>", "filter groups after aggregating"], ["<code>ORDER BY</code>", "sort (<code>DESC</code> for descending)"], ["<code>LIMIT</code>", "keep only the first rows"]])}
<p><strong>Logical evaluation order</strong>: FROM/JOIN &rarr; WHERE &rarr; GROUP BY &rarr; HAVING &rarr; SELECT &rarr; ORDER BY &rarr; LIMIT. That is why you cannot use a SELECT alias inside WHERE, and why HAVING (not WHERE) is used for <code>COUNT(*) &gt; 1</code>.</p>
<h3>Joins</h3>
${table(["Join", "Result"], [["<code>INNER JOIN</code>", "only rows with a match on both sides"], ["<code>LEFT JOIN</code>", "all rows of the left table; NULL where nothing matches (use to find &quot;never ordered&quot;)"], ["<code>CROSS JOIN</code>", "every combination (rarely wanted)"], ["self join", "a table joined to itself (employee and manager)"]])}
<h3>Useful functions and patterns</h3>
<ul><li>Aggregates: <code>COUNT</code>, <code>SUM</code>, <code>AVG</code>, <code>MIN</code>, <code>MAX</code>; <code>COUNT(DISTINCT col)</code>.</li><li><code>LIKE 'A%'</code>, <code>IN (...)</code>, <code>BETWEEN a AND b</code>, <code>IS NULL</code> (never <code>= NULL</code>), <code>COALESCE(x, 0)</code>, <code>CASE WHEN ... END</code>.</li><li>Subquery: <code>WHERE salary &gt; (SELECT AVG(salary) FROM staff)</code>.</li><li>Window functions (SQLite 3.25+): <code>RANK() OVER (PARTITION BY dept ORDER BY salary DESC)</code>.</li><li>Always add <code>ORDER BY</code> when order matters: without it SQL promises no order.</li></ul>`,
  syntax: { code: `SELECT dept, COUNT(*) AS n, AVG(salary) AS avg_pay\nFROM staff\nWHERE active = 1\nGROUP BY dept\nHAVING COUNT(*) >= 2\nORDER BY avg_pay DESC\nLIMIT 3;`, lang: "sql" },
  diagram: chain("Logical order of a query", "Left to right: FROM and JOIN, WHERE, GROUP BY, HAVING, SELECT, ORDER BY, LIMIT.",
    [{ k: "proc", t: "FROM\nJOIN" }, { k: "proc", t: "WHERE" }, { k: "proc", t: "GROUP\nBY" }, { k: "proc", t: "HAVING" }, { k: "proc", t: "SELECT" }, { k: "proc", t: "ORDER\nBY" }, { k: "term", t: "LIMIT" }], { w: 88, gap: 14, hgt: 50 }),
  example: { code: `import sqlite3\n\ndb = sqlite3.connect(":memory:")\ndb.executescript("""\nCREATE TABLE staff (id INTEGER PRIMARY KEY, name TEXT, dept TEXT, salary INTEGER);\nCREATE TABLE depts (code TEXT PRIMARY KEY, title TEXT);\nINSERT INTO depts VALUES ('CSE', 'Computer Science'), ('ECE', 'Electronics'), ('MEC', 'Mechanical');\nINSERT INTO staff (name, dept, salary) VALUES\n ('Asha', 'CSE', 90), ('Ravi', 'CSE', 70), ('Zoya', 'ECE', 80), ('Kiran', 'ECE', 60), ('Meera', 'CSE', 85);\n""")\nq = lambda sql: db.execute(sql).fetchall()\nprint(q("SELECT name FROM staff WHERE salary >= 80 ORDER BY salary DESC"))\nprint(q("SELECT dept, COUNT(*), SUM(salary), ROUND(AVG(salary), 1) FROM staff GROUP BY dept ORDER BY dept"))\nprint(q("SELECT dept FROM staff GROUP BY dept HAVING AVG(salary) > 72"))\nprint(q("SELECT s.name, d.title FROM staff s JOIN depts d ON d.code = s.dept WHERE s.salary > 80 ORDER BY s.name"))\nprint(q("SELECT d.title, COUNT(s.id) FROM depts d LEFT JOIN staff s ON s.dept = d.code GROUP BY d.title ORDER BY d.title"))\nprint(q("SELECT name FROM staff WHERE salary > (SELECT AVG(salary) FROM staff) ORDER BY name"))\nprint(q("SELECT name, CASE WHEN salary >= 85 THEN 'high' ELSE 'normal' END FROM staff ORDER BY id LIMIT 2"))\nprint(q("""SELECT name, dept, RANK() OVER (PARTITION BY dept ORDER BY salary DESC) FROM staff ORDER BY dept, 3"""))`, out: `[('Asha',), ('Meera',), ('Zoya',)]\n[('CSE', 3, 245, 81.7), ('ECE', 2, 140, 70.0)]\n[('CSE',)]\n[('Asha', 'Computer Science'), ('Meera', 'Computer Science')]\n[('Computer Science', 3), ('Electronics', 2), ('Mechanical', 0)]\n[('Asha',), ('Meera',), ('Zoya',)]\n[('Asha', 'high'), ('Ravi', 'normal')]\n[('Asha', 'CSE', 1), ('Meera', 'CSE', 2), ('Ravi', 'CSE', 3), ('Zoya', 'ECE', 1), ('Kiran', 'ECE', 2)]` },
  lineByLine: [["WHERE salary >= 80 ORDER BY salary DESC", "Filter, then sort: Asha 90, Meera 85, Zoya 80."], ["GROUP BY dept", "One result row per department with aggregates."], ["HAVING AVG(salary) > 72", "Keeps groups, not rows: only CSE (81.7) passes; ECE's average is 70."], ["JOIN depts ON ...", "Matches each staff row to its department title."], ["LEFT JOIN + COUNT(s.id)", "Mechanical has no staff, so it still appears with 0."], ["subquery AVG", "The average (77) is computed once and compared with each salary."], ["RANK() OVER (PARTITION BY dept ...)", "A window function ranks within each department without collapsing the rows."]],
  dryRun: { intro: "GROUP BY dept for CSE and ECE:", headers: ["dept", "rows", "COUNT", "SUM(salary)", "AVG"], rows: [["CSE", "90, 70, 85", "3", "245", "81.7"], ["ECE", "80, 60", "2", "140", "70.0"]] },
  realExample: { intro: "Customers who never ordered: a LEFT JOIN plus IS NULL.", code: `import sqlite3\ndb = sqlite3.connect(":memory:")\ndb.executescript("""\nCREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, total INTEGER);\nINSERT INTO customers VALUES (1, 'Asha'), (2, 'Ravi'), (3, 'Zoya');\nINSERT INTO orders VALUES (1, 1, 500), (2, 1, 250), (3, 3, 90);\n""")\nprint(db.execute("SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL").fetchall())\nprint(db.execute("SELECT c.name, SUM(o.total) FROM customers c JOIN orders o ON o.customer_id = c.id GROUP BY c.id ORDER BY 2 DESC").fetchall())`, out: `[('Ravi',)]\n[('Asha', 750), ('Zoya', 90)]` },
  mistakes: ["Using WHERE for an aggregate condition (use HAVING).", "Writing <code>= NULL</code> instead of <code>IS NULL</code>.", "Forgetting ORDER BY and relying on accidental order.", "Joining without an ON condition (a huge cross product).", "Selecting non-aggregated columns that are not in GROUP BY."],
  practices: ["Write queries in the order you think: FROM, WHERE, GROUP BY, then SELECT.", "Alias tables (<code>s</code>, <code>d</code>) in joins.", "Test on a small table first."],
  interview: ["Difference between WHERE and HAVING?", "INNER versus LEFT JOIN?", "Find the second highest salary.", "Find duplicate rows."],
  practiceQs: ["Write a query for the department with the most staff.", "Find customers with more than one order.", "What does COALESCE(x, 0) do?", "Why does the alias in SELECT not work in WHERE?"],
  revision: ["SELECT ... FROM ... WHERE ... GROUP BY ... HAVING ... ORDER BY ... LIMIT.", "WHERE before grouping, HAVING after.", "INNER, LEFT joins; IS NULL.", "Subqueries and window functions."],
  hinglish: "WHERE groups banne se pehle rows filter karta hai aur HAVING groups banne ke baad. LEFT JOIN left table ki saari rows rakhta hai, jahan match na ho wahan NULL aata hai. Order chahiye to hamesha ORDER BY likho.",
  quiz: [
    mcq("Which clause filters groups?", ["WHERE", "HAVING", "ORDER BY", "LIMIT"], 1, "HAVING works after GROUP BY."),
    mcq("Which join keeps all rows from the left table?", ["INNER JOIN", "LEFT JOIN", "CROSS JOIN", "NATURAL"], 1, "Unmatched rows get NULLs."),
    mcq("How do you test for a missing value?", ["= NULL", "IS NULL", "== NULL", "NULL()"], 1, "NULL is never equal to anything."),
    mcq("What does SELECT COUNT(*) FROM t WHERE x > 5 return?", ["The rows themselves", "The number of rows matching", "The sum of x", "Nothing"], 1, "A single number."),
    mcq("What guarantees result order?", ["Insertion order", "ORDER BY", "LIMIT", "The primary key"], 1, "Only ORDER BY does.")
  ],
  tasks: [task("Department payroll", "Read n, then n lines name dept salary. Use SQLite (an in-memory table and a GROUP BY query) to print each department and its total salary, ordered by total salary descending and then by department name, in the form dept total.", "import sqlite3\nn = int(input())\n# create a table, insert the rows, and query with GROUP BY\n", `import sqlite3\nn = int(input())\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE staff (name TEXT, dept TEXT, salary INTEGER)")\nfor _ in range(n):\n    name, dept, salary = input().split()\n    db.execute("INSERT INTO staff VALUES (?, ?, ?)", (name, dept, int(salary)))\nfor dept, total in db.execute("SELECT dept, SUM(salary) FROM staff GROUP BY dept ORDER BY SUM(salary) DESC, dept"):\n    print(dept, total)`, [["5\nAsha CSE 90\nRavi CSE 70\nZoya ECE 80\nKiran ECE 60\nMeera CSE 85", "CSE 245\nECE 140"], ["2\nA X 5\nB Y 5", "X 5\nY 5"]], [["5\nAsha CSE 90\nRavi CSE 70\nZoya ECE 80\nKiran ECE 60\nMeera CSE 85", "CSE 245\nECE 140"], ["2\nA X 5\nB Y 5", "X 5\nY 5"], ["1\nSolo ME 10", "ME 10"], ["4\na P 1\nb Q 9\nc P 9\nd Q 1", "P 10\nQ 10"]])],
});

