lessons.push({
  title: "MySQL Connectivity and Database Drivers",
  minutes: 45,
  learn: ["Connect Python to MySQL with a connector library", "Spot the differences between sqlite3 and server databases", "Keep credentials out of code", "Use connection pooling and handle errors"],
  why: "Most production systems use a database server such as MySQL or PostgreSQL. The Python code is almost the same as for SQLite, but connections, credentials and pooling need care.",
  realWorld: "A web back-end opens a pool of connections to a MySQL server at start-up and borrows one for each request.",
  simple: "Install a driver (<code>mysql-connector-python</code> or <code>PyMySQL</code>), call <code>connect(host, user, password, database)</code>, then use the same cursor, execute and commit pattern as in sqlite3, but with <code>%s</code> placeholders.",
  detail: `<p><strong>Note:</strong> the code in this lesson needs a running MySQL server and an installed driver, so it is shown as a terminal illustration and is <em>not executed</em> by the course checks. The runnable exercises below use standard-library code that you can run anywhere.</p>
<h3>Setup</h3>
${terminal("Terminal (inside your virtual environment)", `$ python -m pip install mysql-connector-python\n# or the pure-Python alternative\n$ python -m pip install pymysql`)}
<h3>Connecting and querying</h3>
${terminal("app.py (needs a MySQL server)", `import os\nimport mysql.connector\n\nconn = mysql.connector.connect(\n    host=os.environ.get("DB_HOST", "localhost"),\n    user=os.environ["DB_USER"],\n    password=os.environ["DB_PASSWORD"],\n    database=os.environ["DB_NAME"],\n)\ncur = conn.cursor(dictionary=True)\ncur.execute("SELECT id, name FROM students WHERE dept = %s", ("CSE",))\nfor row in cur.fetchall():\n    print(row["id"], row["name"])\ncur.close()\nconn.close()`)}
<h3>Differences from SQLite</h3>
${table(["", "SQLite", "MySQL / PostgreSQL"], [["server", "none: a file", "a separate server process, reached over the network"], ["placeholder", "<code>?</code>", "<code>%s</code>"], ["credentials", "none", "host, port, user, password, database (+ TLS)"], ["types", "flexible typing", "strict column types"], ["concurrency", "one writer at a time", "many simultaneous users"], ["auto-increment", "<code>INTEGER PRIMARY KEY</code>", "<code>AUTO_INCREMENT</code> / <code>SERIAL</code>"], ["autocommit", "driver-dependent", "off by default in most drivers: call <code>commit()</code>"]])}
<h3>Good practice</h3>
<ul><li><strong>Credentials</strong>: read them from environment variables or a secrets manager, never from source code or Git.</li><li><strong>Connection pooling</strong>: opening a connection is slow; use a pool (<code>mysql.connector.pooling</code>, or SQLAlchemy's engine) and return connections after use.</li><li>Close cursors and connections (<code>try/finally</code> or <code>contextlib.closing</code>).</li><li>Handle <code>mysql.connector.Error</code> (a subclass of the DB-API <code>Error</code>) and retry only safe operations.</li><li>Use TLS to the server, a dedicated low-privilege user, and parameterised queries.</li><li>Write your code against the DB-API so the driver can be swapped; keep SQL differences in one module.</li></ul>`,
  syntax: { code: `cur.execute("SELECT * FROM t WHERE a = %s AND b = %s", (a, b))\nconn.commit()\n# placeholders differ: sqlite3 uses ?, MySQL drivers use %s`, lang: "python", note: "Same DB-API, different placeholder." },
  diagram: graph("Application, driver and server", "Your Python code calls a driver through the DB-API; the driver talks over the network to the MySQL server which stores the data.", 680, 150,
    [{ id: "a", k: "proc", t: "your Python code", x: 100, y: 75, w: 150, h: 46 }, { id: "d", k: "proc", t: "driver\n(DB-API)", x: 290, y: 75, w: 120, h: 50 }, { id: "n", k: "io", t: "network\n(TLS)", x: 450, y: 75, w: 110, h: 46 }, { id: "s", k: "term", t: "MySQL server", x: 610, y: 75, w: 130, h: 46 }],
    [{ from: "a", to: "d" }, { from: "d", to: "n" }, { from: "n", to: "s" }]),
  example: { code: `import re\n\ndef to_mysql_placeholders(sql):\n    return sql.replace("?", "%s")\n\ndef connection_url(driver, user, host, port, name):\n    return f"mysql+{driver}://{user}@{host}:{port}/{name}"\n\nprint(to_mysql_placeholders("SELECT * FROM t WHERE a = ? AND b = ?"))\nprint(connection_url("pymysql", "app", "db.example.in", 3306, "college"))\n\nimport os\nos.environ["DB_NAME"] = "college"\nprint(os.environ.get("DB_USER", "app_user"), os.environ["DB_NAME"])\n\nclass ConnectionError_(Exception):\n    pass\ndef connect_with_retry(attempts):\n    log = []\n    for n in range(1, attempts + 1):\n        log.append(n)\n        if n == 3:\n            return log\n    raise ConnectionError_("gave up")\nprint(connect_with_retry(5))`, out: `SELECT * FROM t WHERE a = %s AND b = %s\nmysql+pymysql://app@db.example.in:3306/college\napp_user college\n[1, 2, 3]` },
  lineByLine: [["to_mysql_placeholders", "A helper showing the one syntax difference: ? becomes %s."], ["connection_url(...)", "A connection URL never contains the password; that comes from the environment."], ["os.environ.get(\"DB_USER\", \"app_user\")", "Configuration with a safe default."], ["connect_with_retry", "A retry loop pattern for flaky networks (real code also waits between attempts)."]],
  dryRun: { intro: "What happens on a request in a pooled application:", headers: ["Step", "Action"], rows: [["1", "borrow a connection from the pool"], ["2", "execute parameterised SQL"], ["3", "commit (or roll back on error)"], ["4", "return the connection to the pool"]] },
  realExample: { intro: "A wrapper that runs the same function against any DB-API connection: write once, use with sqlite3 or MySQL by changing only the placeholder.", code: `import sqlite3\nPLACEHOLDER = "?"\ndef find_students(conn, dept):\n    sql = f"SELECT name FROM students WHERE dept = {PLACEHOLDER} ORDER BY name"\n    return [r[0] for r in conn.execute(sql, (dept,))]\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE students (name TEXT, dept TEXT)")\ndb.executemany("INSERT INTO students VALUES (?, ?)", [("Ravi", "CSE"), ("Asha", "CSE"), ("Zoya", "ECE")])\nprint(find_students(db, "CSE"))`, out: `['Asha', 'Ravi']` },
  mistakes: ["Hard-coding the password in the source file.", "Using <code>?</code> with a MySQL driver (it expects <code>%s</code>).", "Opening a new connection for every query.", "Forgetting to commit (most drivers do not autocommit).", "Running the app with the MySQL root account."],
  practices: ["Configuration from environment variables.", "Pool connections.", "Keep the SQL and driver details in one module."],
  interview: ["How do you connect Python to MySQL?", "What is connection pooling and why use it?", "How do you keep credentials safe?", "Which placeholder does MySQL use?"],
  practiceQs: ["Why is a connection URL without the password safe to log?", "What would break if you used ? with a MySQL driver?", "How do you retry a failed connection politely?", "Name two other Python database drivers."],
  revision: ["Install a driver; connect(host, user, password, database).", "%s placeholders; commit explicitly.", "Credentials in the environment.", "Pooling; least-privilege user; TLS."],
  hinglish: "MySQL se jodne ke liye mysql-connector-python ya PyMySQL install karo. Placeholder %s hota hai aur commit khud karna padta hai. Password code mein mat likho, environment variable se lo, aur connection pool use karo.",
  quiz: [
    mcq("Which placeholder do MySQL drivers use?", ["?", "%s", "$1", ":x"], 1, "The format style of the DB-API."),
    mcq("Where should the database password come from?", ["The source code", "An environment variable or secrets manager", "A comment", "The URL in Git"], 1, "Never commit credentials."),
    mcq("Why use a connection pool?", ["Opening connections is slow and limited", "It sorts the data", "It creates tables", "It is required by SQL"], 0, "Reuse avoids the setup cost."),
    mcq("What do most MySQL drivers do by default about commits?", ["Autocommit every statement", "Wait for an explicit commit()", "Never commit", "Roll back"], 1, "Call commit() after changes."),
    mcq("What is the DB-API?", ["A standard interface for Python database drivers", "A web framework", "A SQL dialect", "A protocol for emails"], 0, "PEP 249.")
  ],
  tasks: [task("Convert the placeholders", "Read a SQL query written for sqlite3 (with ? placeholders). Print the same query for a MySQL driver (with %s placeholders) and, on the second line, the number of parameters it needs.", "sql = input()\n# convert and count\n", `sql = input()\nprint(sql.replace("?", "%s"))\nprint(sql.count("?"))`, [["SELECT * FROM t WHERE a = ? AND b = ?", "SELECT * FROM t WHERE a = %s AND b = %s\n2"], ["DELETE FROM t", "DELETE FROM t\n0"]], [["SELECT * FROM t WHERE a = ? AND b = ?", "SELECT * FROM t WHERE a = %s AND b = %s\n2"], ["DELETE FROM t", "DELETE FROM t\n0"], ["INSERT INTO t VALUES (?, ?, ?)", "INSERT INTO t VALUES (%s, %s, %s)\n3"], ["UPDATE t SET a = ? WHERE id = ?", "UPDATE t SET a = %s WHERE id = %s\n2"]])],
});

